import { isValid } from 'date-fns';
import { useCallback, useEffect, useRef } from 'react';

import type { TimeValue } from '../../../core/types/time.js';
import { _parseTime } from '../../forms-core/time/timeParser.js';
import type { DateTimeError, DateTimeInputProps } from '../types.js';

export const useDateTimeInputValidation = (
  value: TimeValue | null,
  dateTime: Date | null,
  valueType: TimeValue['type'],
  expressionInputRef: React.RefObject<HTMLSpanElement>,
  validationProps: Pick<
    DateTimeInputProps,
    'onError' | 'min' | 'max' | 'required'
  >,
) => {
  const { onError, min, max, required } = validationProps;

  const errorType = useRef<DateTimeError>(null);

  const isOutsideRange = useCallback(
    (date: Date) => {
      // check lower bound if available
      if (min !== undefined) {
        if (date.getTime() < new Date(min).getTime()) {
          return true;
        }
      }

      // check upper bound if available
      if (max !== undefined) {
        if (date.getTime() > new Date(max).getTime()) {
          return true;
        }
      }

      // within boundaries in this case
      return false;
    },
    [min, max],
  );

  const updateError = useCallback(
    (newErrorType: DateTimeError) => {
      if (newErrorType !== errorType.current) {
        errorType.current = newErrorType;
        onError?.(newErrorType);
      }
    },
    [onError],
  );

  const validateTimeValue = useCallback(
    (value: TimeValue | null) => {
      if (value === null) {
        updateError(required ? 'valueMissing' : null);
      } else if (isOutsideRange(new Date(value.absoluteDate))) {
        updateError('outsideRange');
      } else {
        updateError(null);
      }
    },
    [isOutsideRange, required, updateError],
  );

  const validateExpression = useCallback(
    (expression: string) => {
      if (expression === '') {
        updateError(required ? 'valueMissing' : null);
        return;
      }
      const value = _parseTime(expression);
      if (value === null) {
        updateError('invalid');
        return;
      }

      return validateTimeValue(value);
    },
    [required, updateError, validateTimeValue],
  );

  useEffect(() => {
    // Ignore expression updates, only handle spinbutton update in here
    if (valueType === 'expression') {
      return;
    }

    // e.g. partial date is always invalid
    if (dateTime !== null && !isValid(dateTime)) {
      updateError('invalid');
      return;
    }

    // check if given timestamp is within boundaries
    if (dateTime !== null && isOutsideRange(dateTime)) {
      updateError('outsideRange');
      return;
    }

    // datetime looks fine
    updateError(null);
  }, [dateTime, updateError, isOutsideRange, valueType]);

  // Evaluate the error state based on the current value.
  useEffect(() => {
    // Ignore iso value updates, only focus on expression validation here
    if (value?.type === 'iso8601') {
      return;
    }

    // If the value is null, fallback to the content of the input instead for evaluation
    const expression =
      value?.value ?? expressionInputRef.current?.textContent ?? '';
    const emptyExpression = expression === '';

    if (emptyExpression && required) {
      updateError('valueMissing');
      return;
    }

    // Evaluate if the provided expression is valid or not.
    const parsedValue = _parseTime(expression);

    if (parsedValue && isOutsideRange(new Date(parsedValue.absoluteDate))) {
      updateError('outsideRange');
      return;
    }

    const isBrokenExpression = parsedValue === null && !emptyExpression; // e.g. -2y
    const valid = required ? parsedValue !== null : !isBrokenExpression;
    updateError(valid ? null : 'invalid');

    // no need to put the expressionInputRef into the dep. array
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, required, updateError, isOutsideRange]);

  return {
    validateTimeValue,
    validateExpression,
  };
};
